  const filteredTests = tests.filter((test) =>
    test.testname.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Extract test number for display
  const extractTestNumber = (testname) => {
    const match = testname.match(/\d+/);
    return match ? match[0] : "";
  };
  return (
    <ModalOverlay>
      <ModalContent>
        <ModalHeader>
          <Title>Sort and Select Tests</Title>
        </ModalHeader>

        <SearchContainer>
          <SearchInput
            type="text"
            placeholder="Search tests..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <SearchIcon>
            <Search size={18} />
          </SearchIcon>
        </SearchContainer>

        <SelectAllContainer>
          <CheckboxContainer
            checked={selectAllChecked}
            onClick={handleSelectAll}
          >
            {selectAllChecked && <Check size={14} color="white" />}
          </CheckboxContainer>
          <span>Select All</span>
          {selectedTests.length > 0 && (
            <SelectedCount>{selectedTests.length} selected</SelectedCount>
          )}
        </SelectAllContainer>

        <TestList>
          {filteredTests.length === 0 ? (
            <div
              style={{ padding: "20px", textAlign: "center", color: "#888" }}
            >
              No tests found matching your search
            </div>
          ) : (
            filteredTests.map((test) => {
              const isSelected = selectedTests.some(
                (t) => t.testname === test.testname
              );
              const testNumber = extractTestNumber(test.testname);

              return (
                <TestItem
                  key={test.testname}
                  onClick={() => handleSelectTest(test)}
                >
                  <TestInfo>
                    <CheckboxContainer checked={isSelected}>
                      {isSelected && <Check size={14} color="white" />}
                    </CheckboxContainer>
                    <TestName selected={isSelected}>
  {test.testname}
  {test.NABL && <span className="nabl-asterisk">*</span>} 
</TestName>
                  </TestInfo>
                </TestItem>
              );
            })
          )}
        </TestList>

        <ModalFooter>
          <Button secondary onClick={onClose}>
            <X size={16} />
            Close
          </Button>

          <ButtonGroup>
            <Button
              primary
              disabled={selectedTests.length === 0}
              onClick={() => setShowPrintOptions(!showPrintOptions)}
            >
              <Printer size={16} />
              Print Options
              {showPrintOptions ? (
                <ChevronUp size={16} />
              ) : (
                <ChevronDown size={16} />
              )}
            </Button>

            <PrintOptions show={showPrintOptions}>
              <PrintOption onClick={() => handlePrint(true)}>
                <Printer size={16} />
                Print with Letterhead
              </PrintOption>
              <PrintOption onClick={() => handlePrint(false)}>
                <Printer size={16} />
                Print without Letterhead
              </PrintOption>
            </PrintOptions>
          </ButtonGroup>
        </ModalFooter>
      </ModalContent>
    </ModalOverlay>
  );
};

export default CorporateTestSorting;
